pub type Meters = Float64;

impl From[Float64] for Meters {
  fn from(v: Float64) -> Meters { return v; }
}

impl From[Int] for Meters {
  fn from(v: Int) -> Meters { return v as Float64; }
}

fn main() -> Int {
  let distance: Meters = 100.into();
  return distance as Int;
}
